import android.app.UiAutomation;
import android.os.*;
import android.view.accessibility.AccessibilityNodeInfo;
public final class GpuLocationLayoutProbe {
 static void wideGrid()throws Exception{
  String density=GpuSearchProbe.shell("/system/bin/wm","density"),restore="reset";java.util.regex.Matcher match=java.util.regex.Pattern.compile("Override density: (\\d+)").matcher(density);if(match.find())restore=match.group(1);
  try{for(int dpi:new int[]{220,160}){GpuSearchProbe.shell("/system/bin/wm","density",String.valueOf(dpi));Thread.sleep(1500);android.graphics.Rect longitude=GpuTodoWideProbe.bounds("location-longitude"),latitude=GpuTodoWideProbe.bounds("location-latitude"),accuracy=GpuTodoWideProbe.bounds("location-accuracy"),altitude=GpuTodoWideProbe.bounds("location-altitude");GpuUiProbe.check(longitude.right<latitude.left&&Math.abs(longitude.top-latitude.top)<3,"longitude/latitude share row");if(dpi==220){GpuUiProbe.check(accuracy.top>longitude.bottom&&accuracy.right<altitude.left,"two-column detail grid");}else{GpuUiProbe.check(latitude.right<accuracy.left&&Math.abs(latitude.top-accuracy.top)<3&&altitude.top>longitude.bottom,"three-column detail grid");}GpuRadioProbe.screenshot(dpi==220?"gpu-location-grid-two":"gpu-location-grid-three");}}
  finally{GpuSearchProbe.shell("/system/bin/wm","density",restore);Thread.sleep(1200);}
 }
 public static void main(String[] args)throws Exception{
  HandlerThread t=new HandlerThread("location-layout");t.start();Object c=Class.forName("android.app.UiAutomationConnection").getConstructor().newInstance();UiAutomation a=(UiAutomation)UiAutomation.class.getConstructor(Looper.class,Class.forName("android.app.IUiAutomationConnection")).newInstance(t.getLooper(),c);GpuRadioProbe.automation=a;GpuApiProbe.a=a;GpuWifiLocationProbe.a=a;
  try{UiAutomation.class.getMethod("connect").invoke(a);android.accessibilityservice.AccessibilityServiceInfo info=a.getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;a.setServiceInfo(info);Thread.sleep(1000);
   if(args.length>0){GpuUiProbe.waitText("location-coordinate","W: 105°30' N: 40°15'");GpuUiProbe.waitText("location-longitude","-105.500000");GpuUiProbe.waitText("location-latitude","40.250000");GpuUiProbe.waitText("location-accuracy","0.0m");GpuUiProbe.waitText("location-altitude","0.0m");GpuUiProbe.waitText("location-speed","0.0m/s");GpuRadioProbe.screenshot("gpu-location-result-fixture");wideGrid();GpuApiProbe.click("location-clear");GpuUiProbe.waitText("location-status","No location data available");GpuChromeProbe.back();System.out.println("PASS deterministic Location result fixture; not a real GPS fix");return;}
   GpuChromeProbe.tab("Home");GpuApiProbe.click("home-appearance-light");GpuUiProbe.waitText("home-appearance-resolved","Light");GpuChromeProbe.tab("API");GpuApiProbe.click("api-location");GpuUiProbe.waitText("location-status","No location data available");GpuRadioProbe.screenshot("gpu-location-empty-light");GpuApiProbe.click("location-get");GpuWifiLocationProbe.permission();boolean settled=false;for(int j=0;j<35&&!settled;j++){AccessibilityNodeInfo button=GpuApiProbe.node("location-get");settled=button.isEnabled();button.recycle();if(!settled)Thread.sleep(500);}GpuUiProbe.check(settled,"location request settled");AccessibilityNodeInfo status=GpuRadioProbe.find(a.getRootInActiveWindow(),"location-status");if(status!=null){String text=String.valueOf(status.getText());status.recycle();GpuUiProbe.check(!text.equals("No location data available")&&!text.equals("Getting location..."),"visible device error");System.out.println("Device outcome: visible location error");}else{GpuApiProbe.node("location-coordinate").recycle();System.out.println("Device outcome: real location fix");}GpuRadioProbe.screenshot("gpu-location-device-result");GpuApiProbe.click("location-clear");GpuUiProbe.waitText("location-status","No location data available");GpuChromeProbe.back();
   GpuChromeProbe.tab("Home");GpuApiProbe.click("home-appearance-dark");GpuUiProbe.waitText("home-appearance-resolved","Dark");GpuChromeProbe.tab("API");GpuApiProbe.click("api-location");GpuApiProbe.node("location-get").recycle();GpuShareLayoutProbe.themePixel(true);GpuRadioProbe.screenshot("gpu-location-empty-dark");GpuChromeProbe.back();GpuChromeProbe.tab("Home");GpuApiProbe.click("home-appearance-light");GpuUiProbe.waitText("home-appearance-resolved","Light");System.out.println("PASS Location light/dark empty state, real request settlement and clear");
  }catch(Throwable error){error.printStackTrace();throw error;}finally{UiAutomation.class.getMethod("disconnect").invoke(a);t.quitSafely();}
 }
}
